import { isoCrypto, isoUint8Array } from './iso/index.js';
/**
 * Returns the hash of the given data, using the given algorithm when provided. If `data` is
 * a string, then it's treated like a UTF-8 string. Defaults to hashing using SHA-256.
 */
export function toHash(data, algorithm = -7) {
    if (typeof data === 'string') {
        data = isoUint8Array.fromUTF8String(data);
    }
    const digest = isoCrypto.digest(data, algorithm);
    return digest;
}
